import cases from './choisys-cases.json';

/**
 * Simulated populations for the choisys section. The JSON is generated by the C++ engine
 * (NeoRetroo38/neos-cube: `make cases`, model in docs/SIMULATED-CASES.md); every count, share and similarity in it
 * was computed there. This file only names the rows, columns and products so the landing can label them.
 * To refresh: run `make cases` in neos-cube and copy build/cases.json over choisys-cases.json.
 */
export type Point = [phase: number, row: number, column: number];
export type Axis = { question: string; rows: [string, string, string]; columns: [string, string, string] };
export type Product = { name: string; detail: string; price: string };

export const SIMULATION = cases as unknown as {
  seed: number;
  product: {
    people: number; funnel: number[]; funnelShare: number[]; segmentsCompleted: Record<string, number>;
    counts: number[][]; share: number[][]; after: number[][]; afterN: number[]; afterShare: number[][]; sample: Point[][];
  };
  hiring: {
    funnel: number[]; funnelShare: number[]; reference: Point[]; histogram: number[]; phaseMean: number[];
    ranking: { id: number; archetype: string; similarity: number; phases: number[]; run: Point[] }[];
  };
};

