/** 1-based row and column of a point → its phase-local index 0–8. */
export const cellOf = (row: number, column: number) => (row - 1) * 3 + (column - 1);
/** Spanish number with a decimal comma, exactly as the engine rounded it (no recomputation). */
export const pct = (value: number) => `${value.toLocaleString('es-ES', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} %`;
export const int = (value: number) => value.toLocaleString('es-ES');
